Object.assign(SNIP,{});PRESET_NOTES["l19"]={"Ví dụ: Đếm tần suất bằng map": "Giá trị tới 10⁹ hoặc âm không làm chỉ số mảng được, nhưng làm khóa của map thì được. Duyệt map cho các khóa theo thứ tự tăng.", "Ví dụ: Mua vé bằng multiset": "Khách trả tối đa 4 mua vé 3; khách 8 mua vé 8; khách 3 không còn vé ≤ 3 nên −1; khách 2 cũng −1. Xóa bằng iterator để chỉ mất một vé.", "Ví dụ: Gộp dây bằng min-heap": "Mỗi lần nối hai sợi tốn tổng độ dài của chúng. Luôn nối hai sợi ngắn nhất: 2 + 3 = 5, 4 + 5 = 9, 6 + 9 = 15, tổng 29."};EX_HINTS["l19"]=[["Code mẫu đếm lại cho từng phiếu: O(n²).", "Mã tới 10¹⁸ không dùng làm chỉ số mảng được: map<long long, int>.", "Duyệt map theo khóa tăng dần, chỉ cập nhật khi số phiếu lớn hơn hẳn: tự động chọn mã nhỏ nhất khi bằng nhau."], ["Code mẫu quét mọi vé cho mỗi khách: O(n · m).", "multiset: vé đắt nhất ≤ t là phần tử ngay trước upper_bound(t); nếu upper_bound là begin() thì không có.", "Xóa bằng iterator (ve.erase(it)) để chỉ bán một vé khi có nhiều vé cùng giá."], ["Luôn nối hai đoạn ngắn nhất (tham lam kiểu mã Huffman).", "Code mẫu sắp xếp lại sau mỗi lần nối: O(n² log n). Min-heap lấy hai phần tử nhỏ nhất trong O(log n).", "Chi phí tới khoảng 10¹⁴·log: long long."]];
