const PR19=[{label:"Ví dụ: Đếm tần suất bằng map",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    vector<long long> a = {1000000000, 7, 7, -3, 1000000000, 7};\n    map<long long, int> cnt;\n    for (long long x : a) cnt[x]++;\n    for (auto [x, c] : cnt) cout << x << \": \" << c << \"\\n\";   // khóa tự sắp tăng dần\n    return 0;\n}",viz:[{type:"cont",of:"cnt"}]},{label:"Ví dụ: Mua vé bằng multiset",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    multiset<int> ve = {5, 3, 7, 8, 5};\n    vector<int> khach = {4, 8, 3, 2};    // mỗi khách trả tối đa bao nhiêu\n    for (int t : khach) {\n        auto it = ve.upper_bound(t);     // vé đầu tiên đắt hơn t\n        if (it == ve.begin()) { cout << -1 << \"\\n\"; continue; }\n        --it;                            // vé đắt nhất có giá ≤ t\n        cout << *it << \"\\n\";\n        ve.erase(it);                    // xóa đúng một vé\n    }\n    return 0;\n}",viz:[{type:"cont",of:"ve"},{type:"vars",names:["t"]}]},{label:"Ví dụ: Gộp dây bằng min-heap",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    vector<long long> a = {4, 3, 2, 6};\n    priority_queue<long long, vector<long long>, greater<long long>> pq(a.begin(), a.end());\n    long long chiPhi = 0;\n    while (pq.size() > 1) {\n        long long x = pq.top(); pq.pop();\n        long long y = pq.top(); pq.pop();   // hai sợi ngắn nhất\n        chiPhi += x + y;\n        pq.push(x + y);\n    }\n    cout << chiPhi << \"\\n\";\n    return 0;\n}",viz:[{type:"cont",of:"pq"},{type:"vars",names:["x","y","chiPhi"]}]}];
